ejercicios.solucion:
def secuencia_consecutiva(nums):
    presentes = set(nums)
    mejor = 0
    for x in presentes:
        if x - 1 not in presentes:      # x es el inicio de una secuencia
            largo = 1
            while x + largo in presentes:
                largo += 1
            mejor = max(mejor, largo)
    return mejor

