    pass

ejercicios.solucion:
def contenedor_agua(alturas):
    izq, der = 0, len(alturas) - 1
    mejor = 0
    while izq < der:
        area = min(alturas[izq], alturas[der]) * (der - izq)
        mejor = max(mejor, area)
        if alturas[izq] < alturas[der]:
            izq += 1
        else:
            der -= 1
    return mejor

