ejercicios.solucion:
def sudoku_valido(tablero):
    filas = [set() for _ in range(9)]
    cols = [set() for _ in range(9)]
    cajas = [set() for _ in range(9)]
    for f in range(9):
        for c in range(9):
            d = tablero[f][c]
            if d == ".":
                continue
            b = (f // 3) * 3 + c // 3
            if d in filas[f] or d in cols[c] or d in cajas[b]:
                return False
            filas[f].add(d)
            cols[c].add(d)
            cajas[b].add(d)
    return True

