ejercicios.solucion:
def monedas_minimas(monedas, monto):
    INF = float("inf")
    dp = [0] + [INF] * monto          # dp[m] = mínimo de monedas para m
    for m in range(1, monto + 1):
        for c in monedas:
            if c <= m and dp[m - c] + 1 < dp[m]:
                dp[m] = dp[m - c] + 1
    return -1 if dp[monto] == INF else dp[monto]

