    pass

ejercicios.solucion:
def evaluar_rpn(tokens):
    pila = []
    for t in tokens:
        if t in ("+", "-", "*", "/"):
            b = pila.pop()          # operando derecho
            a = pila.pop()          # operando izquierdo
            if t == "+":
                pila.append(a + b)
            elif t == "-":
                pila.append(a - b)
            elif t == "*":
                pila.append(a * b)
            else:
                pila.append(int(a / b))   # trunca hacia cero
        else:
            pila.append(int(t))
    return pila[0]
